// Font Roboto (Regular + Bold, subset Latin + Vietnamese) nhung san vao jsPDF.
// jsPDF chi co san cac font he thong (Helvetica/Times/Courier) dung WinAnsiEncoding, khong co
// dau tieng Viet — neu khong nhung font that thi chu co dau se bi render sai/gay loi (vi du
// "Cần Thơ" ra "C§n Th¡"). Goi registerVietnameseFont(doc) ngay sau khi tao jsPDF instance
// roi dung font("Roboto", "normal"|"bold") cho moi doc.text/autoTable.
// Nguon: Google Fonts (Roboto), tai qua CSS API voi subset vietnamese+latin.
import type jsPDF from "jspdf";

export const VIETNAMESE_PDF_FONT = "Roboto";
const ROBOTO_REGULAR_BASE64 =
  "";

const ROBOTO_BOLD_BASE64 =
  "";

export function registerVietnameseFont(doc: jsPDF): void {
  doc.addFileToVFS("Roboto-Regular.ttf", ROBOTO_REGULAR_BASE64);
  doc.addFont("Roboto-Regular.ttf", VIETNAMESE_PDF_FONT, "normal");
  doc.addFileToVFS("Roboto-Bold.ttf", ROBOTO_BOLD_BASE64);
  doc.addFont("Roboto-Bold.ttf", VIETNAMESE_PDF_FONT, "bold");
  doc.setFont(VIETNAMESE_PDF_FONT, "normal");
}
